INSERT INTO collection_pages VALUES('c321131c1d88a308817e02bf184b8ef9a3c32e968f0cf0ef2b8c32c6b11a1706','8236b156f6b62411813acbe9422d3db08148a3bf9d944c8058e6d0c90145c67b','{"hasNext":false,"items":[{"author":{"account":{"login":"W-ON","providerType":"User"},"email":"willonovaes@gmail.com","name":"Willian Novaes"},"authoredDate":"2025-10-07T11:59:13Z","committedDate":"2025-10-07T12:05:26Z","committer":{"account":{"login":"W-ON","providerType":"User"},"email":"willonovaes@gmail.com","name":"Willian Novaes"},"observedAt":"2026-10-08T20:33:53.345Z","repositoryId":1071470580,"sha":"c319f5d6e0a5ce0ca3fe718db3cf66e9e10fc535"}],"observedAt":"2026-10-08T20:33:53.345Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/23126146?v=4","events_url":"https://api.github.com/users/W-ON/events{/privacy}","followers_url":"https://api.github.com/users/W-ON/followers","following_url":"https://api.github.com/users/W-ON/following{/other_user}","gists_url":"https://api.github.com/users/W-ON/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/W-ON","id":23126146,"login":"W-ON","node_id":"MDQ6VXNlcjIzMTI2MTQ2","organizations_url":"https://api.github.com/users/W-ON/orgs","received_events_url":"https://api.github.com/users/W-ON/received_events","repos_url":"https://api.github.com/users/W-ON/repos","site_admin":false,"starred_url":"https://api.github.com/users/W-ON/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/W-ON/subscriptions","type":"User","url":"https://api.github.com/users/W-ON","user_view_type":"public"},"comments_url":"https://api.github.com/repos/W-ON/top-micro/commits/c319f5d6e0a5ce0ca3fe718db3cf66e9e10fc535/comments","commit":{"author":{"date":"2025-10-07T11:59:13Z","email":"willonovaes@gmail.com","name":"Willian Novaes"},"comment_count":0,"committer":{"date":"2025-10-07T12:05:26Z","email":"willonovaes@gmail.com","name":"Willian Novaes"},"message":"Initial commit: Microservices architecture with Module Federation\n\n- Backend microservices (NestJS + TCP)\n  - top-users: User management service with DDD architecture\n  - top-finance: Finance management service with DDD architecture\n  - top-api-gateway: HTTP gateway routing to TCP microservices\n\n- Frontend microfrontends (React + Vite + Module Federation)\n  - top-frontend-shell: Main shell app with authentication\n  - top-frontend-users: Users management microfrontend (Material-UI)\n  - top-frontend-finance: Finance management microfrontend (Ant Design)\n\n- Infrastructure\n  - Docker Compose for PostgreSQL databases\n  - Knex.js migrations and seeds\n\nFeatures:\n- TCP communication between microservices\n- Module Federation for microfrontends\n- Pagination and search support\n- Authentication with localStorage persistence\n- Complete CRUD operations","tree":{"sha":"56e2c5a40f32d22ff287034709a4afc7a961870b","url":"https://api.github.com/repos/W-ON/top-micro/git/trees/56e2c5a40f32d22ff287034709a4afc7a961870b"},"url":"https://api.github.com/repos/W-ON/top-micro/git/commits/c319f5d6e0a5ce0ca3fe718db3cf66e9e10fc535","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/23126146?v=4","events_url":"https://api.github.com/users/W-ON/events{/privacy}","followers_url":"https://api.github.com/users/W-ON/followers","following_url":"https://api.github.com/users/W-ON/following{/other_user}","gists_url":"https://api.github.com/users/W-ON/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/W-ON","id":23126146,"login":"W-ON","node_id":"MDQ6VXNlcjIzMTI2MTQ2","organizations_url":"https://api.github.com/users/W-ON/orgs","received_events_url":"https://api.github.com/users/W-ON/received_events","repos_url":"https://api.github.com/users/W-ON/repos","site_admin":false,"starred_url":"https://api.github.com/users/W-ON/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/W-ON/subscriptions","type":"User","