INSERT INTO collection_pages VALUES('67775c88da638f7f08779e64e0ace6926eb8984fa4a4970225b04f645b98e11f','92cefe429b67af202df93e5ccfcfdd4499a5f2897d29dc4f46f847714cf38d60','{"hasNext":false,"items":[{"author":{"account":{"login":"Reza9696","providerType":"User"},"email":"rezamahmood1997@gmail.com","name":"Reza9696"},"authoredDate":"2025-11-25T12:01:40Z","committedDate":"2025-11-25T12:01:40Z","committer":{"account":{"login":"Reza9696","providerType":"User"},"email":"rezamahmood1997@gmail.com","name":"Reza9696"},"observedAt":"2026-10-08T20:33:59.440Z","repositoryId":1071539368,"sha":"207e9340c36894f6755a36bdae7eb4ef85a60e46"}],"observedAt":"2026-10-08T20:33:59.440Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/148342892?v=4","events_url":"https://api.github.com/users/Reza9696/events{/privacy}","followers_url":"https://api.github.com/users/Reza9696/followers","following_url":"https://api.github.com/users/Reza9696/following{/other_user}","gists_url":"https://api.github.com/users/Reza9696/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Reza9696","id":148342892,"login":"Reza9696","node_id":"U_kgDOCNeIbA","organizations_url":"https://api.github.com/users/Reza9696/orgs","received_events_url":"https://api.github.com/users/Reza9696/received_events","repos_url":"https://api.github.com/users/Reza9696/repos","site_admin":false,"starred_url":"https://api.github.com/users/Reza9696/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Reza9696/subscriptions","type":"User","url":"https://api.github.com/users/Reza9696","user_view_type":"public"},"comments_url":"https://api.github.com/repos/toplocs/news-plugin/commits/207e9340c36894f6755a36bdae7eb4ef85a60e46/comments","commit":{"author":{"date":"2025-11-25T12:01:40Z","email":"rezamahmood1997@gmail.com","name":"Reza9696"},"comment_count":0,"committer":{"date":"2025-11-25T12:01:40Z","email":"rezamahmood1997@gmail.com","name":"Reza9696"},"message":"feat: Add Snapchat-style Map Discovery System\n\nPhase 2 Extension: Interactive Map with real-time hotspots\n\n## New Features\n- MapView.vue: Full-screen interactive Leaflet map with dark theme\n- Hotspot System: Simulated activity levels based on POI type + time\n- Community Spots: User-shared locations with photos\n- Events/Meetups: Create and discover local events (IT meetups, etc.)\n- Offers: Local deals displayed on map\n- Local Guide System: \"Show me around\" invite feature\n- Map Search: Search for POIs, spots, events, offers\n\n## New Composables\n- useOSMData.ts: OpenStreetMap Overpass API integration\n- useActivitySimulation.ts: Realistic activity simulation\n- useMapData.ts: Centralized map data management\n\n## New Components\n- MapView.vue: Main map component\n- SpotPopup.vue, EventPopup.vue, OfferPopup.vue: Marker popups\n- SpotSubmitModal.vue: Create new community spots\n- CreateEventModal.vue: Create new events/meetups\n- MapSearch.vue: Search functionality\n- InviteCard.vue: Local guide invitations\n\n## Updated\n- NewsLayout.vue: Feed/Map toggle, integrated map view\n- Added Leaflet + vue-leaflet dependencies\n\n## Documentation\n- docs/map-system.md: Full map system documentation\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nCo-Authored-By: Claude <noreply@anthropic.com>","tree":{"sha":"b79a213322ef5c8f6a681ada028e6f952db1603a","url":"https://api.github.com/repos/toplocs/news-plugin/git/trees/b79a213322ef5c8f6a681ada028e6f952db1603a"},"url":"https://api.github.com/repos/toplocs/news-plugin/git/commits/207e9340c36894f6755a36bdae7eb4ef85a60e46","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/148342892?v=4","events_url":"https://api.github.com/users/Reza9696/events{/privacy}","followers_url":"https://api.github.com/users/Reza9696/followers","following_url":"https://api.github.com/users/Reza9696/following{/other_user}","gists_url":"https://api.github.com/users/Reza9696/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Reza9696","id":148342892,"login":"Reza9696","node_id":"U_kgDOCNeIbA","organizations_url":"https://api.github.com/users/Reza9696/orgs","received_events_url":"https://api.github.com/users/Reza9696/received_events","repos_url":"https://api.github.com/users/Reza9696/repos","site_admin":false,"starred_url":"https://api.github.com/users/Reza9696/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Reza9696/subscriptions","type":"User","url":"https://api.github.com/users/Reza9696","user_view_type":"public"},"html_url":"https://github.com/toplocs/news-plugin/commit/207e9340c36894f6755a36bdae7eb4ef85a60e46","node_id":"C_kwDOP95kqNoAKDIwN2U5MzQwYzM2ODk0ZjY3NTVhMzZiZGFlN2ViNGVmODVhNjBlNDY","parents":[],"sha":"207e9340c36894f6755a36bdae7eb4ef85a60e46","url":"https://api.github.com/repos/toplocs/news-plugin/commits/207e9340c36894f6755a36bdae7eb4ef85a60e46"}],"requestUrl":"https://api.github.com/repos/toplocs/news-plugin/commits?per_page=100&page=1&sha=207e9340c36894f6755a36bdae7eb4ef85a60e46&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A16%3A21.829Z"}');
